/*
 * A041016  Numerators of continued fraction convergents to sqrt(12).
 * https://oeis.org/A041016
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, frac, easy
 * Formula:   not stated
 * Range:     u8 n <= 3, u16 n <= 7, u32 n <= 15, u64 n <= 33, u128 n <= 66,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/**
 * Numerators of the continued fraction convergents to sqrt(12).
 * Sequence A041016.
 *
 * The terms are generated by the standard continuing fraction recurrence:
 *   p_{-2} = 0, p_{-1} = 1
 *   p_k   = a_k * p_{k-1} + p_{k-2}
 * where the partial quotients a_k are produced by the quadratic–surd algorithm
 * for D = 12.
 *
 * The function returns the k‑th numerator a(k) for any non‑negative index k.
 *
 * Complexity: O(k) time, O(1) extra space.
 */

seq_t a(idx_t n)
{
    /* D = 12 (sqrt(12) = 3 + ...), a0 = floor(sqrt(D)) = 3 */
    const idx_t D     = 12;
    const idx_t a0    = 3;

    if (n == 0)
        return (seq_t)a0;       /* a(0) = 3 */

    /* Convergents recurrence: p_{-2}=0, p_{-1}=1, p_0 = a0 */
    seq_t p_minus2 = 0;
    seq_t p_minus1 = 1;
    seq_t p_curr   = (seq_t)a0;   /* numerator for k = 0 */

    /* Continued fraction generation variables for sqrt(D) */
    idx_t m      = 0;          /* m_0 */
    idx_t d      = 1;          /* d_0 */
    idx_t a_curr = a0;         /* a_0 */

    for (idx_t k = 1; k <= n; ++k) {
        /* Next terms of the CF for sqrt(D) */
        idx_t m_next = d * a_curr - m;
        idx_t d_next = (D - m_next * m_next) / d;
        idx_t a_next = (a0 + m_next) / d_next;

        /* Next convergent numerator */
        seq_t p_next = (seq_t)a_next * p_curr + p_minus1;

        /* Shift for next iteration */
        p_minus2 = p_minus1;
        p_minus1 = p_curr;
        p_curr   = p_next;

        m      = m_next;
        d      = d_next;
        a_curr = a_next;
    }

    return p_curr;   /* a(n) */
}
